import{_ as l,c as a,o as i,a4 as e}from"./chunks/framework.CpVK_f0P.js";const _=JSON.parse('{"title":"简介","description":"","frontmatter":{"title":"简介"},"headers":[],"relativePath":"introduce.md","filePath":"introduce.md"}'),r={name:"introduce.md"},t=e('<h2 id="学习状态记录" tabindex="-1">学习状态记录 <a class="header-anchor" href="#学习状态记录" aria-label="Permalink to &quot;学习状态记录&quot;">​</a></h2><h3 id="_2025-年初-暂停学习" tabindex="-1">2025 年初：暂停学习 <a class="header-anchor" href="#_2025-年初-暂停学习" aria-label="Permalink to &quot;2025 年初：暂停学习&quot;">​</a></h3><p>从学习英语开始到结束，持续了一年时间，花费了大概 900 多小时，词汇量稳定在 7500 左右，口语/听力目前大概在 A2 水平，和当时定的目标差得有点多（B2）。目前打算先放一放，因为每天 3-4 小时太累了，占了不少工作时间和学习时间。我觉得英语是不能速成的，得不断的坚持学习才行。</p><h3 id="_2026-年-7-月-恢复学习" tabindex="-1">2026 年 7 月：恢复学习 <a class="header-anchor" href="#_2026-年-7-月-恢复学习" aria-label="Permalink to &quot;2026 年 7 月：恢复学习&quot;">​</a></h3><p>停了一年多，词汇量从 7500 掉到了 6000 左右。这次恢复学习的目标更明确：提升实际交流能力（听懂会议、汇报进度、技术讨论等）。学习计划也做了调整：从每天 3-4 小时降到 60-90 分钟，降低强度换取可持续性；重点从大量输入转向工作场景的输出训练。详见下文「每天学习计划」。</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>我从 24 年 4 月开始下定决心要学好英语，看了一些如何学习英语的文章和资料。最后发现李笑来老师的《<a href="https://github.com/xiaolai/everyone-can-use-english" target="_blank" rel="noreferrer">人人都能用英语</a>》比较靠谱，所以我就开始按照书中的方法开始学习英语，后来又结合了<a href="https://baike.baidu.com/item/%E4%BA%8C%E8%AF%AD%E4%B9%A0%E5%BE%97%E7%90%86%E8%AE%BA/7802838" target="_blank" rel="noreferrer">二语习得理论</a>对学习方法进行了改进。我会在这里记录我的学习过程和心得。</p><p>其实我并不算是完全零基础开始学英语的，我背了好几年单词了，从 17 年开始， 但是一直断断续续，没有一直持续学习，所以刚开始时词汇量在 6000 左右（25 年 1 月又测了一下，已经有 7500 左右了）。</p><p>不过这也仅仅是唯一的优点了，其他的语法、时态、口语等知识都停留在初中阶段。所以要补的知识非常多。这也是我当时每天要投入大量时间学习的原因。</p><p>当时每天学习英语所花的时间大概在 3-4 小时左右，从 4 月开始一直持续到 25 年初，感觉学习效果还不错。</p><h3 id="一年总结" tabindex="-1">一年总结 <a class="header-anchor" href="#一年总结" aria-label="Permalink to &quot;一年总结&quot;">​</a></h3><p>目前听力/口语学习了 900 多个小时，词汇量在 7500 左右，口语/听力水平自我评测大概在 A2 水平，还到不了 B1 水平。但是阅读英文技术文章确实快速了很多，一些简单的英文句子都不需要翻译能够和人直接交流了。</p><h2 id="学习资料" tabindex="-1">学习资料 <a class="header-anchor" href="#学习资料" aria-label="Permalink to &quot;学习资料&quot;">​</a></h2><ul><li>学习路线、指导方针：《人人都能用英语》、二语习得理论</li><li>背单词：墨墨背单词 APP</li><li>语法知识：熟悉 16 种时态，其他语法规则随用随学</li><li>辅助工具：Claude、GPT 等大语言模型</li></ul><h3 id="听力-口语材料按阶段分配" tabindex="-1">听力/口语材料按阶段分配 <a class="header-anchor" href="#听力-口语材料按阶段分配" aria-label="Permalink to &quot;听力/口语材料按阶段分配&quot;">​</a></h3><p>影视只是过渡材料，工作相关内容逐步成为主线：</p><ul><li>第 1-2 个月（重建听力基础）：《走遍美国》为主，搭配 Bluey、BBC 6 Minute English 等带文本的慢速材料；跟读用《走遍美国》原声</li><li>第 3-4 个月（适应正常语速）：美剧（Friends / Modern Family）用于泛听和适应连读，精听主力转向英文技术视频（freeCodeCamp、会议 talk）和 Business English Pod</li><li>第 5 个月起（工作场景为主）：真实会议录音、技术视频、TED 演讲为主，影视降到点缀；跟读用 TED 或发音清晰的技术演讲</li></ul><h3 id="选材原则" tabindex="-1">选材原则 <a class="header-anchor" href="#选材原则" aria-label="Permalink to &quot;选材原则&quot;">​</a></h3><ul><li>精听材料必须带文本或字幕</li><li>跟读材料选发音清晰、语速适中的</li><li>语速快、俚语多的影视只用于泛听</li></ul><h2 id="学习方法演进" tabindex="-1">学习方法演进 <a class="header-anchor" href="#学习方法演进" aria-label="Permalink to &quot;学习方法演进&quot;">​</a></h2><h3 id="初始阶段-基于《人人都能用英语》" tabindex="-1">初始阶段（基于《人人都能用英语》） <a class="header-anchor" href="#初始阶段-基于《人人都能用英语》" aria-label="Permalink to &quot;初始阶段（基于《人人都能用英语》）&quot;">​</a></h3><ol><li>用中文写一段想说的话</li><li>使用 AI 翻译为英文文本</li><li>听英文音频，不懂时对照文本</li><li>确保没有生词后继续听</li><li>背诵内容</li></ol><h3 id="改进后的方法-结合二语习得理论" tabindex="-1">改进后的方法（结合二语习得理论） <a class="header-anchor" href="#改进后的方法-结合二语习得理论" aria-label="Permalink to &quot;改进后的方法（结合二语习得理论）&quot;">​</a></h3><ol><li><p><strong>听力训练</strong></p><ul><li>选择合适的视频材料（如 Family Album USA）</li><li>反复听同一内容</li><li>听不懂时查看台词本，确保没有不认识的单词</li><li>目标是不看台词本的情况下听懂90-95%内容</li><li>达标后进入下一集</li></ul></li><li><p><strong>词汇积累</strong></p><ul><li>收集学习过程中遇到的固定短语进行背诵</li><li>在上下文中学习单词</li><li>通过反复听来巩固</li></ul></li><li><p><strong>语法学习</strong></p><ul><li>系统学习 16 个时态</li><li>其他语法规则随用随学</li><li>在实际应用中加深理解</li></ul></li><li><p><strong>输出训练</strong></p><ul><li>在输入累积 700 多个小时后开始（从 24 年 12 月开始）</li><li>写英语日记和文章</li><li>逐步增加输出量</li></ul></li></ol><h2 id="每天学习计划" tabindex="-1">每天学习计划 <a class="header-anchor" href="#每天学习计划" aria-label="Permalink to &quot;每天学习计划&quot;">​</a></h2><h3 id="旧计划-2024-4-2025-年初" tabindex="-1">旧计划（2024.4 - 2025 年初） <a class="header-anchor" href="#旧计划-2024-4-2025-年初" aria-label="Permalink to &quot;旧计划（2024.4 - 2025 年初）&quot;">​</a></h3><ul><li>每天背单词 100 个（复习+新词），耗时 0.5 小时左右（25 年 2 月已经不再背单词，因为持续了一年，还是一直在 7000 左右，所以放弃了）</li><li>每天练习口语/听力 3 小时，主要是朗读、看视频进行听力/口语练习（原来有背诵对话，现在没有了）</li></ul><h3 id="新计划-2026-7-起" tabindex="-1">新计划（2026.7 起） <a class="header-anchor" href="#新计划-2026-7-起" aria-label="Permalink to &quot;新计划（2026.7 起）&quot;">​</a></h3><p>目标转向实用工作英语，每天 60-90 分钟：</p><ul><li>精听 15-20 分钟：每次只听 1-3 分钟的小段，反复听到不看字幕能懂大意</li><li>跟读 15-20 分钟：逐句模仿原声的重音、停顿、连读</li><li>工作场景表达 15-20 分钟：围绕真实工作练习 stand-up、描述 Bug、确认需求、技术讨论等</li><li>复述/录音/AI 对话 15 分钟：脱稿输出，说完检查问题再说一遍</li><li>用墨墨背单词做维护性复习，每天 10-15 分钟；新词主要从听力和工作材料中收集，放进完整句子里记</li></ul><p>每四周做一次固定测试，测试条件每次保持一致（同题、同时长、同遍数），才能纵向对比：</p><ul><li>两分钟自我介绍 + 三分钟 stand-up + 五分钟项目介绍：内容用自己真实工作，录音存档对比</li><li>听力复述：从固定来源（如某个播客）挑一段没听过的 2 分钟新音频，听两遍后用英语复述主要内容</li><li>十分钟连续对话：AI 语音或真人扮演同事/语伴，开场设定固定，后期逐渐增加真人比例</li><li>写作：10 分钟写一封英文工作消息（汇报进度或描述 Bug）</li><li>词汇量测试：每月用同一工具测一次（墨墨或 testyourvocab.com）</li></ul><p>对比维度：沉默卡顿是否减少、能否说完整句子、是否依赖中译英、能否听懂追问、同题第二遍是否更流畅。四到八周没变化就调整材料难度和输出量，不要盲目坚持。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li>保持学习的持续性和规律性</li><li>确保听力材料的理解度</li><li>循序渐进，不急于求成</li><li>在大量输入的基础上再开始输出</li></ol>',35),o=[t];function n(h,s,u,d,c,p){return i(),a("div",null,o)}const m=l(r,[["render",n]]);export{_ as __pageData,m as default};
